import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { describe, expect, it, vi } from "vitest";
import {
  ackLint, ackRed, ackVerdict, errorClass, findings, flagged, leanDeclared, ledgerIds, parseGolden, parsePremiseArgs,
  premiseLint, premisesCli, report, unknownTheorems, workflowFiles,
} from "../src/premises.ts";

// The TS lint and flag rules are stand-ins for Fw.Ops.Premise (Lean); the golden rows are generated by Lean.
const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const g = parseGolden(readFileSync(join(root, "packages", "contracts", "golden", "ops", "premise.jsonl"), "utf8"));

describe("premise lint and flag agree with the Lean golden", () => {
  it("has the registry and the cases", () => {
    expect(g.premises.length).toBeGreaterThan(0);
    expect(g.lint.length).toBeGreaterThan(0);
    expect(g.flag.length).toBeGreaterThan(0);
  });
  for (const c of g.lint) {
    it(`lint ${c.name}`, () => {
      expect(premiseLint(g.premises, c.tests, c.files)).toEqual({ untested: c.untested, unknown: c.unknown });
    });
  }
  for (const c of g.flag) {
    it(`flag ${c.name}`, () => {
      expect(flagged(g.premises, c.results).map((p) => ({ premise: p.id, theorems: p.theorems }))).toEqual(c.flagged);
    });
  }
});

describe("acknowledged findings agree with the Lean golden (Fw.Ops.Premise.ackVerdict)", () => {
  it("has the acks and the cases", () => {
    expect(g.acks.map((a) => `${a.premise}/${a.engine}`)).toEqual(["anim.list/webkit", "cv.auto-margin/chromium", "cv.auto-margin/webkit"]);
    expect(g.ackCases.find((c) => c.name === "known-run")?.red).toBe(false);
    expect(g.ackCases.filter((c) => c.red).length).toBeGreaterThan(0);
    expect(g.ackLint.length).toBeGreaterThan(0);
    expect(g.errorClass.length).toBeGreaterThan(0);
  });
  for (const c of g.ackCases) {
    it(`ack case ${c.name}`, () => {
      const fs = findings(g.premises, c.results);
      expect(fs).toEqual(c.findings);
      const v = ackVerdict(g.acks, fs);
      expect(v).toEqual({ acked: c.acked, unacked: c.unacked, stale: c.stale });
      expect(ackRed(v)).toBe(c.red);
    });
  }
  for (const c of g.ackLint) {
    it(`ack lint ${c.name}`, () => { expect(ackLint(g.premises, c.ids, c.acks)).toEqual(c.bad); });
  }
  it("error classes", () => {
    for (const c of g.errorClass) expect(errorClass(c.error)).toBe(c.class);
  });
  it("every ack cites an id of research/findings/ledger.json", () => {
    expect(ackLint(g.premises, ledgerIds(root), g.acks)).toEqual([]);
  });
});

describe("registry against the sources", () => {
  it("every non-planned theorem is declared in lean/Fw", () => {
    expect(unknownTheorems(g.premises, leanDeclared(root))).toEqual([]);
  });
  it("a made-up theorem name is reported", () => {
    const p = { ...g.premises[0]!, theorems: ["Fw.Nope.not_a_theorem", "planned:x"] };
    expect(unknownTheorems([p], leanDeclared(root))).toEqual([{ premise: p.id, theorem: "Fw.Nope.not_a_theorem" }]);
  });
  it("the declared browser tests are exactly the registry's page tests, and every lane workflow exists", async () => {
    const m = (await import(pathToFileURL(join(root, "packages", "premise-tests", "src", "tests.mjs")).href)) as { TESTS: { id: string; premise: string }[] };
    expect(premiseLint(g.premises, m.TESTS.map((t) => ({ id: t.id, premise: t.premise })), workflowFiles(root))).toEqual({ untested: [], unknown: [] });
  });
  it("the registry has a lane premise, and dropping its workflow is a lint finding", () => {
    const lanes = g.premises.filter((p) => p.testKind === "lane");
    expect(lanes.map((p) => p.id)).toContain("wktr_scroll_timeline_restyle");
    const tests = g.premises.filter((p) => p.testKind === "page").map((p) => ({ id: p.testId, premise: p.id }));
    const files = workflowFiles(root).filter((f) => !lanes.some((p) => p.testId === f));
    expect(premiseLint(g.premises, tests, files).untested).toEqual(lanes.map((p) => p.id));
  });
});

describe("report and cli", () => {
  const pages = g.premises.filter((p) => p.testKind === "page");
  const all = pages.flatMap((p) => p.engines.map((engine) => ({ testId: p.testId, engine, ok: true })));
  const tests = pages.map((p) => ({ id: p.testId, premise: p.id }));
  const files = workflowFiles(root);
  // The results of CI run 39102911529 as Lean states them (golden ack case `known-run`).
  const known = g.ackCases.find((c) => c.name === "known-run")!.results;
  const ledger = ledgerIds(root);
  const ackedIds = new Set(g.acks.map((a) => a.premise));
  it("the known CI run is ok: its findings are acknowledged and listed separately", () => {
    const r = report(g, tests, files, known, leanDeclared(root), ["chromium", "webkit"], ledger);
    expect(r.ok).toBe(true);
    expect(r.flagged).toEqual([]);
    expect(r.acknowledged.map((a) => `${a.premise}/${a.engine}`)).toEqual(["anim.list/webkit", "cv.auto-margin/chromium", "cv.auto-margin/webkit"]);
    expect(r.holding).toBe(pages.length - 2);
  });
  it("all passing reports the steady acks as stale (remove them), not the intermittent one", () => {
    const r = report(g, tests, files, all, leanDeclared(root), ["chromium", "webkit"], ledger);
    expect(r.ok).toBe(false);
    expect(r.staleAcks.map((a) => `${a.premise}/${a.engine}`)).toEqual(["cv.auto-margin/chromium", "cv.auto-margin/webkit"]);
    expect(r.holding).toBe(pages.length);
  });
  it("a new finding is red next to the acknowledged ones, naming its theorems", () => {
    const p = pages.find((x) => x.theorems.length > 1 && !ackedIds.has(x.id))!;
    const rs = known.map((r) => (r.testId === p.testId && r.engine === "webkit" ? { ...r, ok: false, error: "boom\nmore" } : r));
    const r = report(g, tests, files, rs, null, ["chromium", "webkit"], ledger);
    expect(r.ok).toBe(false);
    expect(r.flagged).toEqual([{ premise: p.id, engines: ["webkit"], reason: "webkit: boom", theorems: p.theorems }]);
    expect(r.acknowledged.length).toBe(3);
  });
  it("an acknowledged premise failing on a new engine, or with a changed value, is red", () => {
    const anim = pages.find((x) => x.id === "anim.list")!;
    const cv = pages.find((x) => x.id === "cv.auto-margin")!;
    const newEngine = known.map((r) => (r.testId === anim.testId && r.engine === "chromium" ? { ...r, ok: false, error: "the short transition is listed while running" } : r));
    const r1 = report(g, tests, files, newEngine, null, ["chromium", "webkit"], ledger);
    expect(r1.ok).toBe(false);
    expect(r1.flagged.map((f) => `${f.premise}/${f.engines.join("+")}`)).toEqual(["anim.list/chromium"]);
    const changed = known.map((r) => (r.testId === cv.testId && r.engine === "webkit" ? { ...r, error: "skipped subtree reports unresolved auto margin, got 151px" } : r));
    const r2 = report(g, tests, files, changed, null, ["chromium", "webkit"], ledger);
    expect(r2.ok).toBe(false);
    expect(r2.flagged[0]?.reason).toContain("got 151px (changed; acknowledged: skipped subtree reports unresolved auto margin, got 150px)");
    expect(r2.staleAcks.map((a) => `${a.premise}/${a.engine}`)).toEqual(["cv.auto-margin/webkit"]);
  });
  it("an ack citing an id missing from the ledger is a lint finding", () => {
    const r = report(g, tests, files, null, null, [], ledger.filter((id) => id !== "premise.anim.list"));
    expect(r.ok).toBe(false);
    expect(r.ackLint.map((a) => a.premise)).toEqual(["anim.list"]);
  });
  it("parses arguments", () => {
    expect(parsePremiseArgs(["--results", "a", "--results", "b", "--json"])).toEqual({ results: ["a", "b"], json: true });
    expect(() => parsePremiseArgs(["--nope"])).toThrow();
    expect(() => parsePremiseArgs(["--results"])).toThrow();
  });
  it("cli: static lint passes, the known run exits 0 listing its acks, a new finding exits 3, bad usage exit 64", async () => {
    const log = vi.spyOn(console, "log").mockImplementation(() => {});
    const err = vi.spyOn(console, "error").mockImplementation(() => {});
    const write = (rs: typeof known) => {
      const dir = mkdtempSync(join(tmpdir(), "premises-"));
      for (const engine of ["chromium", "webkit"] as const) {
        writeFileSync(join(dir, `${engine}.json`), JSON.stringify({ schema: 1, engine, tests, results: rs.filter((r) => r.engine === engine) }));
      }
      return dir;
    };
    try {
      expect(await premisesCli([], root)).toBe(0);
      expect(await premisesCli(["--results", write(known)], root)).toBe(0);
      const out = log.mock.calls.flat().join("\n");
      expect(out).toContain("ACK premise cv.auto-margin on webkit");
      expect(out).toContain("premises: ok");
      log.mockClear();
      const p = pages.find((x) => !ackedIds.has(x.id))!;
      const bad = known.map((r) => (r.testId === p.testId && r.engine === "webkit" ? { ...r, ok: false, error: "x" } : r));
      expect(await premisesCli(["--results", write(bad)], root)).toBe(3);
      expect(log.mock.calls.flat().join("\n")).toContain(`FINDING premise ${p.id}`);
      expect(await premisesCli(["--bogus"], root)).toBe(64);
    } finally { log.mockRestore(); err.mockRestore(); }
  });
});
